// Simulación mínima de WAL: «disco» = lo que sobrevive a un corte; «memoria» = lo que se pierde.
const disco = { paginas: { A: 10, B: 20 }, wal: [], redo: 0 }; // A y B: bultos en dos depósitos
let mem = null, walMem = [], lsn = 0;

function arrancar() { mem = { ...disco.paginas }; walMem = []; }

function transaccion(id, cambios, { commit = true } = {}) {
  for (const [pag, delta] of cambios) {
    mem[pag] += delta;                                       // cambia la página SOLO en memoria
    walMem.push({ lsn: ++lsn, tx: id, pag, delta });         // y anota qué hizo
  }
  if (commit) {
    walMem.push({ lsn: ++lsn, tx: id, commit: true });
    disco.wal.push(...walMem); walMem = [];                  // «fsync» del WAL: recién ahora vale el COMMIT
    console.log(`tx ${id}: COMMIT confirmado (WAL en disco: ${disco.wal.length} registros)`);
  }
}

function checkpoint() { disco.paginas = { ...mem }; disco.redo = lsn; console.log("checkpoint: páginas a disco", JSON.stringify(disco.paginas)); }

function corte() { console.log("--- corte de luz: se pierde la memoria ---"); mem = null; walMem = []; }

function recuperar() {
  const desde = disco.redo;                                   // el checkpoint dice dónde empezar
  mem = { ...disco.paginas };
  const confirmadas = new Set(disco.wal.filter(r => r.commit).map(r => r.tx));
  let rehechos = 0;
  for (const r of disco.wal) {
    if (r.lsn <= desde || r.commit) continue;
    if (!confirmadas.has(r.tx)) continue;                    // sin COMMIT: se ignora
    mem[r.pag] += r.delta; rehechos++;
  }
  console.log(`recuperación: ${rehechos} cambios rehechos ->`, JSON.stringify(mem));
}

arrancar();
transaccion(1, [["A", -3], ["B", +3]]);                      // mover 3 bultos de A a B
checkpoint();                                                 // páginas a disco; hasta acá el WAL ya no hace falta
transaccion(2, [["A", -2], ["B", +2]]);                      // otro traslado, confirmado
transaccion(3, [["A", -5]], { commit: false });              // este nunca llega a confirmarse
corte();
recuperar();
